 const hit=await node.evaluate(n=>{const r=n.getBoundingClientRect(),x=r.x+r.width/2,y=r.y+r.height/2,h=document.elementFromPoint(x,y),body=n.closest('.lw-council-columns').getBoundingClientRect();return{x,y,disabled:n.disabled,insideBody:y>=body.top&&y<=body.bottom,clickable:h===n||n.contains(h)};});
 assert(!hit.disabled&&hit.insideBody&&hit.clickable,'Actual council click must hit the enabled control in its scrollport');
